// AutoScout24 – verificar si la ficha sigue activa.
//
// VIVA   = HTML contiene 'listingDetails' (__NEXT_DATA__) o JSON-LD Car/Vehicle
//          → is_active=TRUE, refresca last_seen_at y last_checked_at
//
// MUERTA = HTML dice 'ya no está disponible' / 'no longer available'
//          O   HTML largo pero sin datos de ficha (redirect a búsqueda /lst/)
//          → is_active=FALSE, actualiza last_checked_at
//
// ERROR  = HTML < 500 chars (timeout, CAPTCHA, red) → no tocar is_active

const dbRecord = $('Loop: oferta por oferta').item.json;
const dbId = String(dbRecord.id || '');

if (!dbId) {
  return { json: { id: null, hasUpdates: false, updateSql: null } };
}

const httpOut = $input.item.json;
const html = typeof httpOut === 'string' ? httpOut
  : (httpOut && (httpOut.data || httpOut.body || httpOut.html) || '');
const s = String(html);
const idEsc = dbId.replace(/'/g, "''");

if (s.length < 500) {
  // Error de red, CAPTCHA o respuesta vacía — no cambiar is_active
  console.log('[as24-verif] id=' + dbId + ' ERROR html_len=' + s.length);
  return { json: { id: dbId, hasUpdates: false, updateSql: null } };
}

// ── Detección de oferta inactiva ──────────────────────────────────────────
const isUnavailable =
  s.includes('ya no est\u00e1 disponible') ||
  s.includes('no longer available') ||
  s.includes('nicht mehr verf\u00fcgbar');

// Redirect a página de búsqueda: tiene 'listings' pero no 'listingDetails'
const isSearchPage =
  /"listings"\s*:\s*\[/.test(s) &&
  !s.includes('listingDetails');

// ── Detección de ficha viva ───────────────────────────────────────────────
const hasListingData =
  s.includes('listingDetails') ||
  /"@type"\s*:\s*"(Car|Vehicle)"/.test(s);

const isDead = isUnavailable || isSearchPage;
const isAlive = !isDead && hasListingData;

console.log('[as24-verif] id=' + dbId +
  ' html=' + s.length +
  ' unavail=' + isUnavailable +
  ' searchPage=' + isSearchPage +
  ' alive=' + isAlive);

if (!isAlive && !isDead) {
  // Ni viva ni muerta confirmadas (ej. CAPTCHA con HTML largo) — no tocar
  return { json: { id: dbId, hasUpdates: false, updateSql: null } };
}

const updateSql = isAlive
  ? "UPDATE moveadvisor_market_offers SET is_active = TRUE, last_seen_at = NOW(), last_checked_at = NOW(), updated_at = NOW() WHERE id = '" + idEsc + "'"
  : "UPDATE moveadvisor_market_offers SET is_active = FALSE, last_checked_at = NOW(), updated_at = NOW() WHERE id = '" + idEsc + "'";

return { json: { id: dbId, hasUpdates: true, updateSql: updateSql, alive: isAlive } };
